package Controllers; import Services.OrderService; import java.io.*; import javax.servlet.*; import javax.servlet.http.*;
public class ViewOrderDetailServlet extends HttpServlet{private final OrderService s=new OrderService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setAttribute("order",s.detail(Integer.parseInt(r.getParameter("id"))));r.setAttribute("statuses",s.statuses());r.getRequestDispatcher("orderDetailsView.jsp").forward(r,p);}}
